-- Agrippa's planetary Intelligences & Spirits, and the Olympic Spirits (Arbatel).
-- 96 new entities, 266 edges. Idempotent + self-validating.
BEGIN;

ON CONFLICT (source_id) DO NOTHING;

CREATE TEMP TABLE _e(id text,name text,etype text,cat text,dom text,conf text,note text) ON COMMIT DROP;

SELECT id,name,'Renaissance Esoteric',etype,cat,dom,'literary',conf,'candidate_verified_name','Renaissance angelic/planetary magic (v1.69.0)',0,false,false,note FROM _e
