INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_KIRCHER_OEDIPUS','primary text','Athanasius Kircher, Oedipus Aegyptiacus (1652-54) — the canonical 72-name roster of the Shem ha-Mephorash','Renaissance Esoteric'),
 ('SRC_ARBATEL','primary text','Arbatel de magia veterum (Basel, 1575) — the seven Olympic Spirits','Renaissance Esoteric'),
 ('SRC_RUDD_GOETIA','primary text','Thomas Rudd, Treatise on Angel Magic / ''The Goetia of Dr Rudd'' (17th c.; ed. Skinner & Rankine) — the Shem-angel vs Goetia-demon pairing','Renaissance Esoteric')
INSERT INTO _e VALUES
 ('ENT_REN_SHEM_72','The Seventy-Two Angels of the Shem ha-Mephorash','Collective','Kabbalistic angel','the 72-fold Name of God; tutelary angels; the 72 quinances of the zodiac','B','The 72 angels derived from the three verses of Exodus 14:19-21 (each a three-letter combination of the divine Name plus the suffix -el or -iah), each governing a 5-degree quinance of the zodiac; in Rudd''s tradition the benevolent counterpart-set to the 72 demons of the Ars Goetia.'),
 ('ENT_REN_AGRIPPA_PLANETARY','Agrippa''s Planetary Intelligences and Spirits','Collective','Renaissance planetary spirit','planetary magic; magic squares (kameas); the seven Intelligence-Spirit pairs','B','The seven paired planetary Intelligences (benevolent directing angels) and Spirits (raw planetary forces) whose names Agrippa derived numerologically from the planetary magic squares in De occulta philosophia II.22.'),
 ('ENT_REN_OLYMPIC_SPIRITS','The Seven Olympic Spirits of the Arbatel','Collective','Olympic spirit','the 196 Olympic provinces; planetary governance','B','The seven planetary Olympic Spirits (Aratron, Bethor, Phaleg, Och, Hagith, Ophiel, Phul) who jointly govern the 196 Olympic provinces of heaven, per the Arbatel de magia veterum (1575).'),
 ('ENT_REN_VEHUIAH','Vehuiah','Shem angel','Kabbalistic angel','new beginnings; willpower; banishing evil','B','The 1st Shem angel (root VHV, Exodus 14:19), ruling the first Aries quinance under Mars; office is willpower, new beginnings, and banishing evil spirits.'),
 ('ENT_REN_JELIEL','Jeliel','Shem angel','Kabbalistic angel','love; fidelity; reconciliation','B','The 2nd Shem angel (root YLY), ruling Aries 5-10° under Mars; office is love, conjugal fidelity, and reconciliation.'),
 ('ENT_REN_SITAEL','Sitael','Shem angel','Kabbalistic angel','protection; high enterprise','B','The 3rd Shem angel (root SYT), ruling Aries 10-15° under Sol; office is protection against adversity and nobility in great enterprise.'),
 ('ENT_REN_ELEMIAH','Elemiah','Shem angel','Kabbalistic angel','protection; voyages; revealing traitors','B','The 4th Shem angel (root OLM), ruling Aries 15-20° under Sol; office is safe voyages, protection of sailors, and exposing traitors.'),
 ('ENT_REN_MAHASIAH','Mahasiah','Shem angel','Kabbalistic angel','peace; learning; rectification','B','The 5th Shem angel (root MHSh), ruling Aries 20-25° under Venus; office is living in peace and ease in learning the liberal sciences.'),
 ('ENT_REN_LELAHEL','Lelahel','Shem angel','Kabbalistic angel','healing; light; renown','B','The 6th Shem angel (root LLH), ruling Aries 25-30° under Venus; office is light, the healing of illness, and renown in arts and science.'),
 ('ENT_REN_ACHAIAH','Achaiah','Shem angel','Kabbalistic angel','patience; hidden knowledge; nature''s secrets','B','The 7th Shem angel (root AKA), ruling Taurus 0-5° under Mercury; office is patience and the discovery of the secrets of nature.'),
 ('ENT_REN_CAHETEL','Cahetel','Shem angel','Kabbalistic angel','agriculture; blessing; abundance','B','The 8th Shem angel (root KHT), ruling Taurus 5-10° under Mercury; office is divine blessing and agricultural abundance.'),
 ('ENT_REN_HAZIEL','Haziel','Shem angel','Kabbalistic angel','mercy; reconciliation; friendship','B','The 9th Shem angel (root HZY), ruling Taurus 10-15° under Luna; office is divine mercy, forgiveness, and reconciliation.'),
 ('ENT_REN_ALADIAH','Aladiah','Shem angel','Kabbalistic angel','healing; grace; absolution','B','The 10th Shem angel (root ALD), ruling Taurus 15-20° under Luna; office is healing, divine grace, and the remission of guilt.'),
 ('ENT_REN_LAUVIAH_11','Lauviah','Shem angel','Kabbalistic angel','victory; renown; fortune','B','The 11th Shem angel (root LAV), ruling Taurus 20-25° under Saturn; office is victory, renown, and favour of the great.'),
 ('ENT_REN_HAHAIAH','Hahaiah','Shem angel','Kabbalistic angel','refuge; revelation; dreams','B','The 12th Shem angel (root HHO), ruling Taurus 25-30° under Saturn; office is refuge and the revelation of mysteries through dreams.'),
 ('ENT_REN_IEZALEL','Iezalel','Shem angel','Kabbalistic angel','fidelity; reconciliation; learning','B','The 13th Shem angel (root YZL), ruling Gemini 0-5° under Jupiter; office is fidelity, reconciliation, and skill in learning.'),
 ('ENT_REN_MEBAHEL','Mebahel','Shem angel','Kabbalistic angel','justice; truth; protection','B','The 14th Shem angel (root MHB), ruling Gemini 5-10° under Jupiter; office is justice, truth, and protection of the oppressed.'),
 ('ENT_REN_HARIEL','Hariel','Shem angel','Kabbalistic angel','purification; knowledge; craft','B','The 15th Shem angel (root HRY), ruling Gemini 10-15° under Mars; office is purity of faith and skill in useful arts and sciences.'),
 ('ENT_REN_HEKAMIAH','Hekamiah','Shem angel','Kabbalistic angel','protection; loyalty; deliverance','B','The 16th Shem angel (root HQM), ruling Gemini 15-20° under Mars; office is protection of rulers and deliverance from treachery.'),
 ('ENT_REN_LAUVIAH_17','Lauviah (II)','Shem angel','Kabbalistic angel','revelation; prophecy; high sciences','B','The 17th Shem angel (root LAV), ruling Gemini 20-25° under Sol; office is revelation and prophetic inspiration through dreams.'),
 ('ENT_REN_CALIEL','Caliel','Shem angel','Kabbalistic angel','justice; truth; exposure of guilt','B','The 18th Shem angel (root KLY), ruling Gemini 25-30° under Sol; office is justice and the exposure of guilt in lawsuits.'),
 ('ENT_REN_LEUVIAH','Leuviah','Shem angel','Kabbalistic angel','memory; knowledge; grace','B','The 19th Shem angel (root LVV), ruling Cancer 0-5° under Venus; office is expansive memory, intelligence, and grace.'),
 ('ENT_REN_PAHALIAH','Pahaliah','Shem angel','Kabbalistic angel','piety; virtue; conversion','B','The 20th Shem angel (root PHL), ruling Cancer 5-10° under Venus; office is piety, chastity, and religious vocation.'),
 ('ENT_REN_NELCHAEL','Nelchael','Shem angel','Kabbalistic angel','knowledge; learning; banishing evil','B','The 21st Shem angel (root NLK), ruling Cancer 10-15° under Mercury; office is the liberal sciences, astronomy, and protection against slander.'),
 ('ENT_REN_YEIAYEL','Yeiayel','Shem angel','Kabbalistic angel','fortune; commerce; protection','B','The 22nd Shem angel (root YYY), ruling Cancer 15-20° under Mercury; office is fame, fortune, and success in commerce and travel.'),
 ('ENT_REN_MELAHEL','Melahel','Shem angel','Kabbalistic angel','healing; protection; courage','B','The 23rd Shem angel (root MHL), ruling Cancer 20-25° under Luna; office is healing through medicinal plants and safe travel.'),
 ('ENT_REN_HAHEUIAH','Haheuiah','Shem angel','Kabbalistic angel','protection; refuge; defence','B','The 24th Shem angel (root HHO), ruling Cancer 25-30° under Luna; office is protection of exiles, fugitives, and refuge-seekers.'),
 ('ENT_REN_NITH_HAIAH','Nith-Haiah','Shem angel','Kabbalistic angel','magic; hidden knowledge; wisdom','B','The 25th Shem angel (root NTH), ruling Leo 0-5° under Saturn; office is wisdom, the occult arts, and magic.'),
 ('ENT_REN_HAAIAH','Haaiah','Shem angel','Kabbalistic angel','wisdom; truth; justice','B','The 26th Shem angel (root HAA), ruling Leo 5-10° under Saturn; office is political wisdom, diplomacy, and truth in judgment.'),
 ('ENT_REN_YERATHEL','Yerathel','Shem angel','Kabbalistic angel','truth; justice; deliverance','B','The 27th Shem angel (root YRT), ruling Leo 10-15° under Jupiter; office is the spread of light and truth and confounding slanderers.'),
 ('ENT_REN_SEHEIAH','Seheiah','Shem angel','Kabbalistic angel','healing; protection; long life','B','The 28th Shem angel (root ShAH), ruling Leo 15-20° under Jupiter; office is long life, health, and protection against accident.'),
 ('ENT_REN_REIYEL','Reiyel','Shem angel','Kabbalistic angel','deliverance; revelation; piety','B','The 29th Shem angel (root RYY), ruling Leo 20-25° under Mars; office is deliverance from evil influences and divine inspiration.'),
 ('ENT_REN_OMAEL','Omael','Shem angel','Kabbalistic angel','fertility; agriculture; healing','B','The 30th Shem angel (root AVM), ruling Leo 25-30° under Mars; office is fertility, multiplication, and the natural and medical kingdoms.'),
 ('ENT_REN_LECABEL','Lecabel','Shem angel','Kabbalistic angel','agriculture; knowledge; illumination','B','The 31st Shem angel (root LKB), ruling Virgo 0-5° under Sol; office is talent in agriculture and intellectual illumination.'),
 ('ENT_REN_VASARIAH','Vasariah','Shem angel','Kabbalistic angel','justice; eloquence; memory','B','The 32nd Shem angel (root VShR), ruling Virgo 5-10° under Sol; office is justice tempered by clemency, and eloquence.'),
 ('ENT_REN_YEHUIAH','Yehuiah','Shem angel','Kabbalistic angel','protection; order; revealing traitors','B','The 33rd Shem angel (root YHV), ruling Virgo 10-15° under Venus; office is order, protection of rulers, and exposure of conspiracies.'),
 ('ENT_REN_LEHAHIAH','Lehahiah','Shem angel','Kabbalistic angel','order; fortune; loyalty','B','The 34th Shem angel (root LHH), ruling Virgo 15-20° under Venus; office is obedience, calming of anger, and good fortune in service.'),
 ('ENT_REN_CHAVAKIAH','Chavakiah','Shem angel','Kabbalistic angel','reconciliation; love; peace','B','The 35th Shem angel (root KVQ), ruling Virgo 20-25° under Mercury; office is reconciliation and harmony among kin.'),
 ('ENT_REN_MENADEL','Menadel','Shem angel','Kabbalistic angel','craft; vocation; recovery','B','The 36th Shem angel (root MNT), ruling Virgo 25-30° under Mercury; office is steadfast work, vocation, and the return of what is lost.'),
 ('ENT_REN_ANIEL','Aniel','Shem angel','Kabbalistic angel','protection; victory over obstacles','B','The 37th Shem angel (root ANY), ruling Libra 0-5° under Venus; office is breaking impediments and protection in adversity.'),
 ('ENT_REN_HAAMIAH','Haamiah','Shem angel','Kabbalistic angel','truth; ritual worship','B','The 38th Shem angel (root HOM), ruling Libra 5-10° under Mercury; office is religious worship and the acquisition of esoteric truth.'),
 ('ENT_REN_REHAEL','Rehael','Shem angel','Kabbalistic angel','healing; love','B','The 39th Shem angel (root RHO), ruling Libra 10-15° under Luna; office is the healing of body and mind and filial love.'),
 ('ENT_REN_IEIAZEL','Ieiazel','Shem angel','Kabbalistic angel','healing; craft','B','The 40th Shem angel (root YYZ), ruling Libra 15-20° under Saturn; office is consolation, deliverance from captivity, and inspiration of the arts.'),
 ('ENT_REN_HAHAHEL','Hahahel','Shem angel','Kabbalistic angel','protection; revelation','B','The 41st Shem angel (root HHH), ruling Libra 20-25° under Jupiter; office is the protection and zeal of missionaries and martyrs.'),
 ('ENT_REN_MIKAEL','Mikael (Shem angel)','Shem angel','Kabbalistic angel','protection; truth','B','The 42nd Shem angel (root MYK), ruling Libra 25-30° under Mars; office is statecraft, diplomacy, and the unmasking of plots (distinct from the archangel Michael).'),
 ('ENT_REN_VEULIAH','Veuliah','Shem angel','Kabbalistic angel','wealth; fortune','B','The 43rd Shem angel (root VVL), ruling Scorpio 0-5° under Sol; office is prosperity, peace, and the success of enterprises.'),
 ('ENT_REN_YELAHIAH','Yelahiah','Shem angel','Kabbalistic angel','war; justice','B','The 44th Shem angel (root YLH), ruling Scorpio 5-10° under Venus; office is victory in just war and protection of warriors and magistrates.'),
 ('ENT_REN_SEHALIAH','Sehaliah','Shem angel','Kabbalistic angel','healing; agriculture','B','The 45th Shem angel (root SAL), ruling Scorpio 10-15° under Mercury; office is the revival of vital force and the quickening of plants.'),
 ('ENT_REN_ARIEL','Ariel (Shem angel)','Shem angel','Kabbalistic angel','hidden knowledge; revelation','B','The 46th Shem angel (root ORY), ruling Scorpio 15-20° under Luna; office is the revelation of hidden treasures and secrets of nature.'),
 ('ENT_REN_ASALIAH','Asaliah','Shem angel','Kabbalistic angel','wisdom; truth','B','The 47th Shem angel (root OShL), ruling Scorpio 20-25° under Saturn; office is the contemplation of divine justice and truth.'),
 ('ENT_REN_MIHAEL','Mihael (Shem angel)','Shem angel','Kabbalistic angel','love; fertility','B','The 48th Shem angel (root MHSh), ruling Scorpio 25-30° under Jupiter; office is conjugal fidelity, friendship, and procreation (distinct from the archangel Michael).'),
 ('ENT_REN_VEHUEL','Vehuel','Shem angel','Kabbalistic angel','wisdom; revelation','B','The 49th Shem angel (root VHV), ruling Sagittarius 0-5° under Mars; office is elevation of the spirit, magnanimity, and literary inspiration.'),
 ('ENT_REN_DANIEL','Daniel (Shem angel)','Shem angel','Kabbalistic angel','justice; truth','B','The 50th Shem angel (root DNY), ruling Sagittarius 5-10° under Sol; office is eloquence and merciful judgment (distinct from the prophet Daniel).'),
 ('ENT_REN_HAHASIAH','Hahasiah','Shem angel','Kabbalistic angel','hidden knowledge; healing','B','The 51st Shem angel (root HHSh), ruling Sagittarius 10-15° under Venus; office is occult knowledge of natural medicine and alchemy.'),
 ('ENT_REN_IMAMIAH','Imamiah','Shem angel','Kabbalistic angel','protection; war','B','The 52nd Shem angel (root OMM), ruling Sagittarius 15-20° under Mercury; office is the liberation of prisoners and victory over foes.'),
 ('ENT_REN_NANAEL','Nanael','Shem angel','Kabbalistic angel','knowledge; wisdom','B','The 53rd Shem angel (root NNA), ruling Sagittarius 20-25° under Luna; office is the higher sciences, theology, and contemplation.'),
 ('ENT_REN_NITHAEL','Nithael','Shem angel','Kabbalistic angel','fortune; protection','B','The 54th Shem angel (root NYT), ruling Sagittarius 25-30° under Saturn; office is the endurance of legitimate authority, grace, and long life.'),
 ('ENT_REN_MEBAHIAH','Mebahiah','Shem angel','Kabbalistic angel','fertility; truth','B','The 55th Shem angel (root MBH), ruling Capricorn 0-5° under Jupiter; office is offspring, the propagation of piety, and clarity of conscience.'),
 ('ENT_REN_POYEL','Poyel','Shem angel','Kabbalistic angel','fortune; wealth','B','The 56th Shem angel (root PVY), ruling Capricorn 5-10° under Mars; office is good fortune, public favour, and fulfilment of wishes.'),
 ('ENT_REN_NEMAMIAH','Nemamiah','Shem angel','Kabbalistic angel','war; fortune','B','The 57th Shem angel (root NMM), ruling Capricorn 10-15° under Sol; office is the success of commanders and just causes and the deliverance of captives.'),
 ('ENT_REN_YEIALEL','Yeialel','Shem angel','Kabbalistic angel','healing; truth','B','The 58th Shem angel (root YYL), ruling Capricorn 15-20° under Venus; office is healing of the eyes and mind and firmness of judgment.'),
 ('ENT_REN_HARAHEL','Harahel','Shem angel','Kabbalistic angel','knowledge; wealth','B','The 59th Shem angel (root HRH), ruling Capricorn 20-25° under Mercury; office is knowledge, the guardianship of archives, and the prosperity of letters.'),
 ('ENT_REN_MITZRAEL','Mitzrael','Shem angel','Kabbalistic angel','healing; justice','B','The 60th Shem angel (root MTzR), ruling Capricorn 25-30° under Luna; office is relief from mental affliction, reconciliation, and just elevation.'),
 ('ENT_REN_UMABEL','Umabel','Shem angel','Kabbalistic angel','knowledge; love','B','The 61st Shem angel (root VMB), ruling Aquarius 0-5° under Saturn; office is astronomy, natural philosophy, and the cultivation of friendship.'),
 ('ENT_REN_IAH_HEL','Iah-Hel','Shem angel','Kabbalistic angel','wisdom; hidden knowledge','B','The 62nd Shem angel (root YHH), ruling Aquarius 5-10° under Jupiter; office is the contemplative life, philosophical wisdom, and peaceful retreat.'),
 ('ENT_REN_ANAUEL','Anauel','Shem angel','Kabbalistic angel','wealth; protection','B','The 63rd Shem angel (root ANV), ruling Aquarius 10-15° under Mars; office is the prosperity of trade, the safety of commerce, and concord.'),
 ('ENT_REN_MEHIEL','Mehiel','Shem angel','Kabbalistic angel','protection; craft','B','The 64th Shem angel (root MHY), ruling Aquarius 15-20° under Sol; office is the protection and inspiration of writers, professors, and orators.'),
 ('ENT_REN_DAMABIAH','Damabiah','Shem angel','Kabbalistic angel','protection; wisdom','B','The 65th Shem angel (root DMB), ruling Aquarius 20-25° under Venus; office is safety at sea, success in maritime enterprise, and the gaining of wisdom.'),
 ('ENT_REN_MANAKEL','Manakel','Shem angel','Kabbalistic angel','healing; truth','B','The 66th Shem angel (root MNQ), ruling Aquarius 25-30° under Mercury; office is reconciliation, the soothing of wrath, and the calming of dreams.'),
 ('ENT_REN_EYAEL','Eyael','Shem angel','Kabbalistic angel','hidden knowledge; wisdom','B','The 67th Shem angel (root AYO), ruling Pisces 0-5° under Luna; office is comfort in hardship, esoteric knowledge, and contemplation of eternity.'),
 ('ENT_REN_HABUHIAH','Habuhiah','Shem angel','Kabbalistic angel','healing; agriculture','B','The 68th Shem angel (root HBV), ruling Pisces 5-10° under Saturn; office is the cure of illness, the fecundity of the soil, and abundant harvests.'),
 ('ENT_REN_ROCHEL','Rochel','Shem angel','Kabbalistic angel','hidden knowledge; justice','B','The 69th Shem angel (root RAH), ruling Pisces 10-15° under Jupiter; office is the recovery of lost goods, the discovery of thieves, and rightful inheritance.'),
 ('ENT_REN_JABAMIAH','Jabamiah','Shem angel','Kabbalistic angel','fertility; magic','B','The 70th Shem angel (root YBM), ruling Pisces 15-20° under Mars; office is the regeneration of nature, alchemical transmutation, and spiritual renewal.'),
 ('ENT_REN_HAIAIEL','Haiaiel','Shem angel','Kabbalistic angel','war; protection','B','The 71st Shem angel (root HYY), ruling Pisces 20-25° under Sol; office is bravery, martial triumph, and the deliverance of the just.'),
 ('ENT_REN_MUMIAH','Mumiah','Shem angel','Kabbalistic angel','healing; death','B','The 72nd and final Shem angel (root MVM), ruling Pisces 25-30° under Venus; office is the completion of works, recovery of health, and the cycle of death and renewal.'),
 ('ENT_REN_AGIEL','Agiel','Planetary intelligence','Renaissance planetary spirit','directing intelligence of Saturn; time; limitation; structure; longevity','B','The Intelligence (directing angel) of Saturn, its name drawn from the Saturn magic square in Agrippa II.22; paired with the Saturn Spirit Zazel.'),
 ('ENT_REN_ZAZEL','Zazel','Planetary spirit','Renaissance planetary spirit','raw force of Saturn; restriction; decay; time','B','The Spirit (raw force) of Saturn from the Saturn magic square in Agrippa II.22, the more dangerous counterpart to the Intelligence Agiel.'),
 ('ENT_REN_IOPHIEL','Iophiel','Planetary intelligence','Renaissance planetary spirit','directing intelligence of Jupiter; expansion; fortune; sovereignty; justice','B','The Intelligence of Jupiter (Yophiel), its name drawn from the Jupiter magic square in Agrippa II.22; paired with the Jupiter Spirit Hismael.'),
 ('ENT_REN_HISMAEL','Hismael','Planetary spirit','Renaissance planetary spirit','raw force of Jupiter; expansion; increase','B','The Spirit (raw force) of Jupiter from the Jupiter magic square in Agrippa II.22, counterpart to the Intelligence Iophiel.'),
 ('ENT_REN_GRAPHIEL','Graphiel','Planetary intelligence','Renaissance planetary spirit','directing intelligence of Mars; war; force; courage; iron','B','The Intelligence of Mars, its name drawn from the Mars magic square in Agrippa II.22; paired with the Mars Spirit Bartzabel.'),
 ('ENT_REN_BARTZABEL','Bartzabel','Planetary spirit','Renaissance planetary spirit','raw force of Mars; war; violence; destruction','B','The Spirit (raw force) of Mars from the Mars magic square in Agrippa II.22, counterpart to the Intelligence Graphiel.'),
 ('ENT_REN_NAKHIEL','Nakhiel','Planetary intelligence','Renaissance planetary spirit','directing intelligence of the Sun; light; kingship; gold; vitality','B','The Intelligence of Sol, its name drawn from the Sun magic square in Agrippa II.22; paired with the solar Spirit Sorath.'),
 ('ENT_REN_SORATH','Sorath','Planetary spirit','Renaissance planetary spirit','raw force of the Sun; solar power (number 666)','B','The Spirit (raw force) of Sol from the Sun magic square in Agrippa II.22 (its name summing to 666), counterpart to the Intelligence Nakhiel.'),
 ('ENT_REN_HAGIEL','Hagiel','Planetary intelligence','Renaissance planetary spirit','directing intelligence of Venus; love; beauty; harmony; copper','B','The Intelligence of Venus, its name drawn from the Venus magic square in Agrippa II.22; paired with the Venus Spirit Kedemel.'),
 ('ENT_REN_KEDEMEL','Kedemel','Planetary spirit','Renaissance planetary spirit','raw force of Venus; desire; attraction; pleasure','B','The Spirit (raw force) of Venus from the Venus magic square in Agrippa II.22, counterpart to the Intelligence Hagiel.'),
 ('ENT_REN_TIRIEL','Tiriel','Planetary intelligence','Renaissance planetary spirit','directing intelligence of Mercury; intellect; communication; commerce; magic','B','The Intelligence of Mercury, its name drawn from the Mercury magic square in Agrippa II.22; paired with the Mercury Spirit Taphthartharath.'),
 ('ENT_REN_TAPHTHARTHARATH','Taphthartharath','Planetary spirit','Renaissance planetary spirit','raw force of Mercury; intellect; trickery; rapid motion','B','The Spirit (raw force) of Mercury from the Mercury magic square in Agrippa II.22, counterpart to the Intelligence Tiriel.'),
 ('ENT_REN_MALKAH_BE_TARSHISHIM','Malkah be-Tarshishim ve-ad Ruachoth Schechalim','Planetary intelligence','Renaissance planetary spirit','directing intelligence of the Moon; tides; cycles; dreams; silver','B','The Intelligence (intelligence of intelligences) of Luna, her long name drawn from the Moon magic square in Agrippa II.22; paired with the lunar Spirit Chashmodai.'),
 ('ENT_REN_CHASHMODAI','Chashmodai','Planetary spirit','Renaissance planetary spirit','raw force of the Moon; tides; flux','B','The Spirit (raw force) of Luna from the Moon magic square in Agrippa II.22 (cognate with the demon Asmodeus), counterpart to the lunar Intelligence.'),
 ('ENT_REN_ARATRON','Aratron','Olympic spirit','Olympic spirit','alchemy; magic; familiars; invisibility; longevity','B','The Olympic Spirit of Saturn governing 49 of the 196 Olympic provinces; offices include alchemy, magic, familiars, invisibility, and longevity.'),
 ('ENT_REN_BETHOR','Bethor','Olympic spirit','Olympic spirit','aerial spirits; dignities; treasures; medicines; long life','B','The Olympic Spirit of Jupiter governing 42 of the 196 Olympic provinces; offices include commanding aerial spirits, granting dignities and treasures, and prolonging life.'),
 ('ENT_REN_PHALEG','Phaleg','Olympic spirit','Olympic spirit','war; conflict; military honour','B','The Olympic Spirit of Mars governing 35 of the 196 Olympic provinces, called the Lord of War, presiding over matters martial.'),
 ('ENT_REN_OCH','Och','Olympic spirit','Olympic spirit','alchemy and gold; medicine; perfect health; longevity','B','The Olympic Spirit of Sol governing 28 of the 196 Olympic provinces; offices include alchemy/gold, medicine, perfect health, and longevity.'),
 ('ENT_REN_HAGITH','Hagith','Olympic spirit','Olympic spirit','love; beauty; transmutation; familiars','B','The Olympic Spirit of Venus governing 21 of the 196 Olympic provinces, presiding over love and beauty and bestowing beauty and faithful familiars.'),
 ('ENT_REN_OPHIEL','Ophiel','Olympic spirit','Olympic spirit','the Mercurial arts; all sciences; the philosopher''s stone; familiars','B','The Olympic Spirit of Mercury governing 14 of the 196 Olympic provinces; offices include the Mercurial arts, all sciences, and the philosopher''s stone.'),
 ('ENT_REN_PHUL','Phul','Olympic spirit','Olympic spirit','silver; water-spirits; healing; long life','B','The Olympic Spirit of Luna governing 7 of the 196 Olympic provinces, called the Lord of the Powers of the Moon, presiding over silver, water-spirits, and healing.');
