INSERT INTO _s VALUES
 ('ENT_REN_SHEM_72','SRC_KIRCHER_OEDIPUS','The 72 angels derived from the three verses of Exodus 14:19-21 (each a three-letter combination of the divine Name plus the suffix -el or -iah), each governing a 5-degree quinance of the zodiac; in Rudd''s tradition the benevolent counterpart-set to the 72 demons of the Ars Goetia.','primary text attestation'),
 ('ENT_REN_AGRIPPA_PLANETARY','SRC_AGRIPPA_OCCULTA','The seven paired planetary Intelligences (benevolent directing angels) and Spirits (raw planetary forces) whose names Agrippa derived numerologically from the planetary magic squares in De occulta philosophia II.22.','primary text attestation'),
 ('ENT_REN_OLYMPIC_SPIRITS','SRC_ARBATEL','The seven planetary Olympic Spirits (Aratron, Bethor, Phaleg, Och, Hagith, Ophiel, Phul) who jointly govern the 196 Olympic provinces of heaven, per the Arbatel de magia veterum (1575).','primary text attestation'),
 ('ENT_REN_VEHUIAH','SRC_KIRCHER_OEDIPUS','The 1st Shem angel (root VHV, Exodus 14:19), ruling the first Aries quinance under Mars; office is willpower, new beginnings, and banishing evil spirits.','primary text attestation'),
 ('ENT_REN_JELIEL','SRC_KIRCHER_OEDIPUS','The 2nd Shem angel (root YLY), ruling Aries 5-10° under Mars; office is love, conjugal fidelity, and reconciliation.','primary text attestation'),
 ('ENT_REN_SITAEL','SRC_KIRCHER_OEDIPUS','The 3rd Shem angel (root SYT), ruling Aries 10-15° under Sol; office is protection against adversity and nobility in great enterprise.','primary text attestation'),
 ('ENT_REN_ELEMIAH','SRC_KIRCHER_OEDIPUS','The 4th Shem angel (root OLM), ruling Aries 15-20° under Sol; office is safe voyages, protection of sailors, and exposing traitors.','primary text attestation'),
 ('ENT_REN_MAHASIAH','SRC_KIRCHER_OEDIPUS','The 5th Shem angel (root MHSh), ruling Aries 20-25° under Venus; office is living in peace and ease in learning the liberal sciences.','primary text attestation'),
 ('ENT_REN_LELAHEL','SRC_KIRCHER_OEDIPUS','The 6th Shem angel (root LLH), ruling Aries 25-30° under Venus; office is light, the healing of illness, and renown in arts and science.','primary text attestation'),
 ('ENT_REN_ACHAIAH','SRC_KIRCHER_OEDIPUS','The 7th Shem angel (root AKA), ruling Taurus 0-5° under Mercury; office is patience and the discovery of the secrets of nature.','primary text attestation'),
 ('ENT_REN_CAHETEL','SRC_KIRCHER_OEDIPUS','The 8th Shem angel (root KHT), ruling Taurus 5-10° under Mercury; office is divine blessing and agricultural abundance.','primary text attestation'),
