INSERT INTO _p VALUES
 ('ENT_REN_SHEM_72','PER_EARLY_MODERN_OCCULT','The 72 angels derived from the three verses of Exodus 14:19-21 (each a three-letter combination of the divine Name plus the suffix -el or -iah), each governing a 5-degree quinance of the zodiac; in Rudd''s tradition the benevolent counterpart-set to the 72 demons of the Ars Goetia.'),
 ('ENT_REN_AGRIPPA_PLANETARY','PER_EARLY_MODERN_OCCULT','The seven paired planetary Intelligences (benevolent directing angels) and Spirits (raw planetary forces) whose names Agrippa derived numerologically from the planetary magic squares in De occulta philosophia II.22.'),
 ('ENT_REN_OLYMPIC_SPIRITS','PER_EARLY_MODERN_OCCULT','The seven planetary Olympic Spirits (Aratron, Bethor, Phaleg, Och, Hagith, Ophiel, Phul) who jointly govern the 196 Olympic provinces of heaven, per the Arbatel de magia veterum (1575).'),
 ('ENT_REN_VEHUIAH','PER_EARLY_MODERN_OCCULT','The 1st Shem angel (root VHV, Exodus 14:19), ruling the first Aries quinance under Mars; office is willpower, new beginnings, and banishing evil spirits.'),
 ('ENT_REN_JELIEL','PER_EARLY_MODERN_OCCULT','The 2nd Shem angel (root YLY), ruling Aries 5-10° under Mars; office is love, conjugal fidelity, and reconciliation.'),
 ('ENT_REN_SITAEL','PER_EARLY_MODERN_OCCULT','The 3rd Shem angel (root SYT), ruling Aries 10-15° under Sol; office is protection against adversity and nobility in great enterprise.'),
