INSERT INTO _r VALUES
 ('ENT_REN_SHEM_72','opposes','ENT_GOE_ARS_GOETIA','medium','In Rudd''s tradition (Treatise on Angel Magic / ''Goetia of Dr Rudd'') the 72 Shem ha-Mephorash angels are the benevolent counterpart-set that constrains the 72 demons of the Ars Goetia; the specific one-to-one pairings vary between tabulations, so the opposition is modeled at the set level.','SRC_RUDD_GOETIA'),
